import{_ as n,o as r,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const k=JSON.parse('{"title":"Ursprung und Wesen des Dunkel-Ersetzungskörpers","description":"","frontmatter":{},"headers":[],"relativePath":"de/57-黑暗置换体起源与本质.md","filePath":"de/57-黑暗置换体起源与本质.md","lastUpdated":null}'),s={name:"de/57-黑暗置换体起源与本质.md"};function d(l,e,u,g,a,o){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="ursprung-und-wesen-des-dunkel-ersetzungskorpers" tabindex="-1">Ursprung und Wesen des Dunkel-Ersetzungskörpers <a class="header-anchor" href="#ursprung-und-wesen-des-dunkel-ersetzungskorpers" aria-label="Permalink to &quot;Ursprung und Wesen des Dunkel-Ersetzungskörpers&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Punkt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>57</td></tr><tr><td>Modul</td><td>Rassen und Lebensformen</td></tr><tr><td>Kernschlüsselwörter</td><td>Dunkel-Ersetzungskörper, Abgrundenergie, Doppelseeelen-Koexistenz, Ursprung und Wesen, Bedrohung der Symbiose</td></tr></tbody></table><h2 id="i-definition-des-dunkel-ersetzungskorpers" tabindex="-1">I. Definition des Dunkel-Ersetzungskörpers <a class="header-anchor" href="#i-definition-des-dunkel-ersetzungskorpers" aria-label="Permalink to &quot;I. Definition des Dunkel-Ersetzungskörpers&quot;">​</a></h2><p>Im Hengyuanzhou (Ursprungsuniversum aller Wesen) bezieht sich „Dunkel-Ersetzungskörper&quot; auf ein Lebewesen, dessen ursprüngliche Seele nach der Korrosion durch Abgrundenergie oder andere Dunkelenergien teilweise oder vollständig durch Dunkelenergie ersetzt wurde, wodurch eine besondere Lebensform entstand, in der die ursprüngliche Seele und die Dunkelseele koexistieren. Der Dunkel-Ersetzungskörper ist nicht einfach ein „Lebewesen, das mit Dunkelenergie infiziert ist&quot;, sondern hat eine Ersetzung und Rekonstruktion auf Seelenebene durchlaufen — sein Wesen ist die Existenz von zwei sich widersprechenden, aber voneinander abhängigen Seelen in einem Körper: der ursprünglichen Wirtsseele und der Dunkel-Ersetzungsseele.</p><p>Der Dunkel-Ersetzungskörper ist eines der komplexesten Probleme der Lebensethik und Sicherheitsgovernance, mit denen die Anker-Symbiose-Zivilisation konfrontiert ist. Er unterscheidet sich von fremdem Leben (fremdes Leben ist ein völlig neues, unbekanntes Leben, während der Dunkel-Ersetzungskörper das Produkt eines bekannten, transformierten Lebens ist) und auch von gewöhnlichen Energieinfizierten (bei gewöhnlichen Infizierten ist nur der Körper korrodiert, während die Seele des Dunkel-Ersetzungskörpers bereits ersetzt wurde). Seine Besonderheit liegt in der Beteiligung von Rechtskonflikten, ethischen Dilemmata und Sicherheitsrisiken zweier Seelen, die spezielle Identifikations-, Ethik- und Behandlungsregeln erfordern.</p><h2 id="ii-ursprung-des-dunkel-ersetzungskorpers" tabindex="-1">II. Ursprung des Dunkel-Ersetzungskörpers <a class="header-anchor" href="#ii-ursprung-des-dunkel-ersetzungskorpers" aria-label="Permalink to &quot;II. Ursprung des Dunkel-Ersetzungskörpers&quot;">​</a></h2><p>Die Entstehung des Dunkel-Ersetzungskörpers erfordert bestimmte Bedingungen und Prozesse, sein Ursprung lässt sich auf folgende Aspekte zurückführen:</p><h3 id="a-quelle-der-abgrundenergie" tabindex="-1">(A) Quelle der Abgrundenergie <a class="header-anchor" href="#a-quelle-der-abgrundenergie" aria-label="Permalink to &quot;(A) Quelle der Abgrundenergie&quot;">​</a></h3><p>Die Abgrundenergie ist der Kernfaktor bei der Entstehung des Dunkel-Ersetzungskörpers. Die Abgrundenergie stammt aus dem kosmischen Abgrund — der dunkelsten Region des Hengyuanzhou, in der sich die ursprüngliche Dunkelenergie ansammelt, die zu Beginn der Kosmoserschaffung abgestoßen wurde. Die Abgrundenergie weist folgende Eigenschaften auf:</p><table tabindex="0"><thead><tr><th>Eigenschaft</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Korrosivität</td><td>Die Abgrundenergie kann den Körper und die Seele von Lebewesen korrodieren und sie allmählich in Dunkelattribute verwandeln</td></tr><tr><td>Verführungskraft</td><td>Die Abgrundenergie kann die negativen Emotionen und Wünsche von Lebewesen verstärken und sie dazu verleiten, aktiv Dunkelenergie zu akzeptieren</td></tr><tr><td>Ersetzbarkeit</td><td>Die Abgrundenergie kann bei Erreichen einer bestimmten Konzentration die Seele eines Lebewesens ersetzen und eine Dunkel-Ersetzungsseele bilden</td></tr><tr><td>Ansteckungsfähigkeit</td><td>Der Dunkel-Ersetzungskörper kann Abgrundenergie durch Kontakt, Angriff, Bewusstseinsinvasion usw. auf andere Lebewesen übertragen</td></tr><tr><td>Evolutionsfähigkeit</td><td>Die Abgrundenergie kann sich mit der Evolution des Wirts weiterentwickeln und stärkere Dunkelfähigkeiten hervorbringen</td></tr></tbody></table><h3 id="b-entstehungsbedingungen" tabindex="-1">(B) Entstehungsbedingungen <a class="header-anchor" href="#b-entstehungsbedingungen" aria-label="Permalink to &quot;(B) Entstehungsbedingungen&quot;">​</a></h3><p>Die Entstehung des Dunkel-Ersetzungskörpers erfordert die gleichzeitige Erfüllung folgender Bedingungen:</p><ol><li><strong>Exposition gegenüber Abgrundenergie</strong>: Das Lebewesen ist hochkonzentrierter Abgrundenergie ausgesetzt oder steht langfristig mit niedrigkonzentrierter Abgrundenergie in Kontakt.</li><li><strong>Phase der seelischen Verletzlichkeit</strong>: Die Seele des Lebewesens befindet sich in einem verletzlichen Zustand, wie z. B. Kultivierungsdurchbruch, schwere Verletzungen, extreme emotionale Schwankungen, geistiger Zusammenbruch usw.</li><li><strong>Katalysator durch negative Emotionen</strong>: Das Lebewesen weist intensive negative Emotionen auf, wie Groll, Angst, Gier, Verzweiflung usw. Diese Emotionen sind die besten Katalysatoren für die Abgrundenergie.</li><li><strong>Aktive oder passive Akzeptanz</strong>: Das Lebewesen akzeptiert aktiv die Dunkelkraft unter der Verführung der Abgrundenergie oder wird passiv korrodiert, wenn es nicht widerstehen kann.</li><li><strong>Vollständige Seelenersetzung</strong>: Die Abgrundenergie wurzelt in der Seele und schließt die Ersetzung ab, wodurch eine unabhängige Dunkel-Ersetzungsseele entsteht.</li></ol><h3 id="c-entstehungswege" tabindex="-1">(C) Entstehungswege <a class="header-anchor" href="#c-entstehungswege" aria-label="Permalink to &quot;(C) Entstehungswege&quot;">​</a></h3><p>Der Dunkel-Ersetzungskörper entsteht hauptsächlich auf folgenden Wegen:</p><ul><li><strong>Kontakt mit der Abgrundregion</strong>: Das Lebewesen dringt in den kosmischen Abgrund oder in Regionen mit austretender Abgrundenergie ein und wird von hochkonzentrierter Abgrundenergie korrodiert.</li><li><strong>Transformation von Dunkelkultivierern</strong>: Der Kultivierer praktiziert aktiv Dunkel-Kultivierungsmethoden, absorbiert langfristig Abgrundenergie und wird schließlich von der Dunkelseele ersetzt.</li><li><strong>Infektion durch einen Dunkel-Ersetzungskörper</strong>: Wird von einem bereits existierenden Dunkel-Ersetzungskörper angegriffen oder einer Bewusstseinsinvasion unterzogen, wobei Abgrundenergie durch Wunden oder Bewusstseinskanäle eindringt.</li><li><strong>Fluch von Ruinen und alten Artefakten</strong>: Tritt in Kontakt mit alten Ruinen oder verfluchten Gegenständen, die mit Abgrundenergie kontaminiert sind, und wird von der darin gespeicherten Dunkelenergie korrodiert.</li><li><strong>Experimenteller Unfall</strong>: Bei Experimenten im Zusammenhang mit Abgrundenergie kommt es zu einem Unfall, bei dem das Versuchspersonal von unkontrollierter Abgrundenergie korrodiert wird.</li><li><strong>Invasion durch Dimensionsrisse</strong>: Dunkelwesen, die durch Dimensionsrisse aus der Abgrunddimension eindringen, ersetzen direkt die Seele lokaler Lebewesen.</li></ul><h2 id="iii-wesen-des-dunkel-ersetzungskorpers" tabindex="-1">III. Wesen des Dunkel-Ersetzungskörpers <a class="header-anchor" href="#iii-wesen-des-dunkel-ersetzungskorpers" aria-label="Permalink to &quot;III. Wesen des Dunkel-Ersetzungskörpers&quot;">​</a></h2><p>Das Wesen des Dunkel-Ersetzungskörpers ist ein „Doppelseeelen-Koexistenzkörper&quot;, seine Kernmerkmale sind wie folgt:</p><h3 id="a-doppelseeelen-struktur" tabindex="-1">(A) Doppelseeelen-Struktur <a class="header-anchor" href="#a-doppelseeelen-struktur" aria-label="Permalink to &quot;(A) Doppelseeelen-Struktur&quot;">​</a></h3><p>Im Körper des Dunkel-Ersetzungskörpers existieren zwei unabhängige Seelen:</p><table tabindex="0"><thead><tr><th>Seele</th><th>Name</th><th>Merkmale</th></tr></thead><tbody><tr><td>Ursprüngliche Wirtsseele</td><td>Die ursprüngliche Seele des Wirts</td><td>Behält die Erinnerungen, Persönlichkeit, das Bewusstsein und die Emotionen des ursprünglichen Wirts bei, aber ihre Kraft wird von der Dunkelseele unterdrückt</td></tr><tr><td>Ersetzungsseele</td><td>Die aus der Kondensation von Abgrundenergie gebildete Dunkelseele</td><td>Besitzt unabhängiges Bewusstsein, Erinnerungen und Persönlichkeit, ist mächtig und neigt zur Dunkelheit und zur Plünderung</td></tr></tbody></table><p>Die beiden Seelen teilen sich denselben Körper und kämpfen um die Kontrolle über den Körper. In den meisten Fällen nimmt die Dunkel-Ersetzungsseele die dominante Position ein, und die ursprüngliche Wirtsseele wird in die Tiefen des Bewusstseins verdrängt; aber unter bestimmten Bedingungen (wie intensive emotionale Stimulation, Reinigung durch Lichtenergie, Explosion des Willens des ursprünglichen Wirts) kann die ursprüngliche Wirtsseele vorübergehend die Kontrolle über den Körper zurückerlangen.</p><h3 id="b-konflikt-und-abhangigkeit-der-seelen" tabindex="-1">(B) Konflikt und Abhängigkeit der Seelen <a class="header-anchor" href="#b-konflikt-und-abhangigkeit-der-seelen" aria-label="Permalink to &quot;(B) Konflikt und Abhängigkeit der Seelen&quot;">​</a></h3><p>Zwischen den beiden Seelen besteht ein komplexes Verhältnis von Konflikt und Abhängigkeit:</p><ul><li><strong>Konfliktfähigkeit</strong>: Die beiden Seelen kämpfen um die Kontrolle über den Körper; die ursprüngliche Wirtsseele versucht, die Dunkelseele zu vertreiben, um die Freiheit wiederzuerlangen, während die Dunkelseele versucht, die ursprüngliche Wirtsseele vollständig zu vernichten, um den Körper vollständig zu kontrollieren.</li><li><strong>Abhängigkeit</strong>: Die beiden Seelen teilen sich denselben Körper und dieselbe Lebensurquelle; das Erlöschen einer Seele kann zum Erlöschen der anderen oder zum Zusammenbruch des Körpers führen. Die Dunkelseele benötigt die ursprüngliche Wirtsseele als „Anker&quot;, um ihre Existenz in der materiellen Welt aufrechtzuerhalten, während die ursprüngliche Wirtsseele (bei tiefer Ersetzung) die Kraft der Dunkelseele benötigt, um den Körper am Laufen zu halten.</li><li><strong>Möglichkeit der Fusion</strong>: In extrem seltenen Fällen können die beiden Seelen eine Versöhnung erreichen, eine Seelenfusion verwirklichen und eine neue Seele bilden, die sowohl die Erinnerungen des ursprünglichen Wirts als auch die Dunkelkraft vereint.</li></ul><h3 id="c-fahigkeitsmerkmale" tabindex="-1">(C) Fähigkeitsmerkmale <a class="header-anchor" href="#c-fahigkeitsmerkmale" aria-label="Permalink to &quot;(C) Fähigkeitsmerkmale&quot;">​</a></h3><p>Der Dunkel-Ersetzungskörper weist normalerweise folgende Fähigkeitsmerkmale auf:</p><ol><li><strong>Kontrolle über Dunkelenergie</strong>: Kann Abgrundenergie und Energie mit Dunkelattributen kontrollieren und Dunkelzauber sowie Angriffe ausführen.</li><li><strong>Körperverstärkung</strong>: Der Körper ist durch Abgrundenergie verstärkt, Kraft, Geschwindigkeit und Verteidigung übertreffen die gewöhnlicher Lebewesen bei weitem.</li><li><strong>Regenerationsfähigkeit</strong>: Besitzt eine starke Regenerationsfähigkeit, gewöhnliche Verletzungen können schnell heilen.</li><li><strong>Infektionsfähigkeit</strong>: Kann Abgrundenergie durch Angriff oder Kontakt auf andere Lebewesen übertragen und neue Dunkel-Ersetzungskörper schaffen.</li><li><strong>Verbesserte Wahrnehmung</strong>: Besitzt eine extrem starke Wahrnehmung von Dunkelenergie, negativen Emotionen und Lebensatem.</li><li><strong>Gestaltwandel</strong>: Kann sich in eine Dunkelgestalt oder eine Monstergestalt verwandeln und die Kampfkraft weiter steigern.</li><li><strong>Seelenangriff</strong>: Kann direkt die Seele anderer Lebewesen angreifen und Seelenverletzungen oder Seelenverschmutzung verursachen.</li></ol><h3 id="d-verhaltenstendenzen" tabindex="-1">(D) Verhaltenstendenzen <a class="header-anchor" href="#d-verhaltenstendenzen" aria-label="Permalink to &quot;(D) Verhaltenstendenzen&quot;">​</a></h3><p>Die Verhaltenstendenzen des Dunkel-Ersetzungskörpers hängen davon ab, welche Seele dominiert:</p><ul><li><strong>Wenn die Dunkelseele dominiert</strong>: Das Verhalten neigt zu Zerstörung, Plünderung, Tötung und Verbreitung von Dunkelenergie, mit starker Aggressivität und antisozialen Tendenzen.</li><li><strong>Wenn die ursprüngliche Wirtsseele dominiert</strong>: Das Verhalten neigt zur ursprünglichen Persönlichkeit und den Werten des Wirts, wird aber von der Dunkelenergie beeinflusst, Emotionen schwanken leichter und sind leichter reizbar.</li><li><strong>Während des Konflikts der beiden Seelen</strong>: Das Verhalten zeigt Chaos und Widerspruch, kann zwischen Klarheit und Kontrollverlust wechseln und ist sowohl für sich selbst als auch für andere gefährlich.</li></ul><h2 id="iv-entwicklungsstadien-des-dunkel-ersetzungskorpers" tabindex="-1">IV. Entwicklungsstadien des Dunkel-Ersetzungskörpers <a class="header-anchor" href="#iv-entwicklungsstadien-des-dunkel-ersetzungskorpers" aria-label="Permalink to &quot;IV. Entwicklungsstadien des Dunkel-Ersetzungskörpers&quot;">​</a></h2><p>Der Dunkel-Ersetzungskörper durchläuft von der Korrosion bis zur vollständigen Ersetzung normalerweise folgende Entwicklungsstadien:</p><table tabindex="0"><thead><tr><th>Stadium</th><th>Name</th><th>Merkmale</th><th>Reversibilität</th></tr></thead><tbody><tr><td>Erstes Stadium</td><td>Phase der Energiekorrosion</td><td>Die Abgrundenergie beginnt, den Körper zu korrodieren, körperliche Beschwerden und emotionale Schwankungen treten auf, die Seele wurde noch nicht ersetzt</td><td>Vollständig reversibel</td></tr><tr><td>Zweites Stadium</td><td>Phase der Seelenverschmutzung</td><td>Die Abgrundenergie dringt in die Seele ein, die ursprüngliche Wirtsseele wird verschmutzt, Persönlichkeitsveränderungen und Dunkelimpulse treten auf</td><td>Größtenteils reversibel</td></tr><tr><td>Drittes Stadium</td><td>Phase der Doppelseeelenbildung</td><td>Die Dunkel-Ersetzungsseele bildet sich, die Struktur der Doppelseeelen-Koexistenz ist etabliert, die ursprüngliche Wirtsseele beginnt unterdrückt zu werden</td><td>Teilweise reversibel</td></tr><tr><td>Viertes Stadium</td><td>Phase der Dunkeldominanz</td><td>Die Dunkelseele nimmt vollständig die dominante Position ein, die ursprüngliche Wirtsseele wird tief unterdrückt, der Körper ist grundsätzlich durch Dunkelenergie transformiert</td><td>Schwer reversibel</td></tr><tr><td>Fünftes Stadium</td><td>Phase der vollständigen Ersetzung</td><td>Die ursprüngliche Wirtsseele wurde vollständig vernichtet oder assimiliert, die Dunkelseele kontrolliert vollständig den Körper und wird zu einem reinen Dunkelwesen</td><td>Irreversibel</td></tr></tbody></table><p>Im ersten bis dritten Stadium hat der Dunkel-Ersetzungskörper noch die Möglichkeit der Genesung; nach Eintritt in das vierte Stadium ist die Schwierigkeit der Genesung extrem groß; im fünften Stadium existiert der ursprüngliche Wirt nicht mehr, er kann nur als reines Dunkelwesen behandelt werden.</p><h2 id="v-beziehung-zwischen-dem-dunkel-ersetzungskorper-und-der-symbiose-zivilisation" tabindex="-1">V. Beziehung zwischen dem Dunkel-Ersetzungskörper und der Symbiose-Zivilisation <a class="header-anchor" href="#v-beziehung-zwischen-dem-dunkel-ersetzungskorper-und-der-symbiose-zivilisation" aria-label="Permalink to &quot;V. Beziehung zwischen dem Dunkel-Ersetzungskörper und der Symbiose-Zivilisation&quot;">​</a></h2><p>Der Dunkel-Ersetzungskörper ist eine große Herausforderung, vor der die Anker-Symbiose-Zivilisation steht, seine Beziehung zur Symbiose-Zivilisation zeigt sich in folgenden Aspekten:</p><ol><li><strong>Ideologiekonflikt</strong>: Die Dunkelseele des Dunkel-Ersetzungskörpers neigt zu Plünderung und Zerstörung, was grundsätzlich der Ideologie der Symbiose-Zivilisation „Anti-Plünderung, Förderung der Symbiose&quot; widerspricht.</li><li><strong>Sicherheitsbedrohung</strong>: Der Dunkel-Ersetzungskörper besitzt starke Kampfkraft und Infektionsfähigkeit und stellt eine direkte Bedrohung für die Sicherheit der Symbiose-Zivilisation dar.</li><li><strong>Ethisches Dilemma</strong>: Die ursprüngliche Wirtsseele im Dunkel-Ersetzungskörper ist ein legitimes Mitglied der Symbiose-Zivilisation, deren Grundrechte geschützt werden sollten, aber die Gefährlichkeit der Dunkelseele erfordert auch Kontrollmaßnahmen; wie man beide ausbalanciert, ist ein tiefes ethisches Dilemma.</li><li><strong>Governance-Herausforderung</strong>: Die Identifizierung, Isolierung, Behandlung und Entsorgung des Dunkel-Ersetzungskörpers erfordert spezielle Systeme und Ressourcen, was hohe Anforderungen an die Governance-Fähigkeit der Symbiose-Zivilisation stellt.</li><li><strong>Transformationsmöglichkeit</strong>: Wenn die ursprüngliche Wirtsseele noch existiert, können durch Reinigung, Fusion, Trennung und andere Mittel einige Dunkel-Ersetzungskörper gerettet und wieder in das Symbiose-System integriert werden.</li></ol><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Der Dunkel-Ersetzungskörper ist ein besonderes Wesen, das aus der Verflechtung von Abgrundenergie und der Seele von Lebewesen entsteht, sein Wesen ist eine widersprüchliche Einheit der Doppelseeelen-Koexistenz. Er ist nicht nur eine Bedrohung für die Sicherheit der Symbiose-Zivilisation, sondern auch ein Test für die ethische Tiefe und die Governance-Fähigkeit der Symbiose-Zivilisation. Das Verständnis des Ursprungs und Wesens des Dunkel-Ersetzungskörpers ist die Voraussetzung und Grundlage für die Formulierung der Doppelseeelen-Ethikgrundsätze (siehe „58-Doppelseeelen-Ethikgrundsätze&quot;) und der Vier-Zweig-Behandlungsregeln (siehe „59-Vier-Zweig-Behandlung des Dunkel-Ersetzungskörpers&quot;).</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>58-Doppelseeelen-Ethikgrundsätze</li><li>59-Vier-Zweig-Behandlung des Dunkel-Ersetzungskörpers</li><li>55-Klassifizierung und Eigenschaften der fremden Energie</li><li>53-Identifikationskriterien für fremdes Leben</li></ul>',42)])])}const b=n(s,[["render",d]]);export{k as __pageData,b as default};
